questions.question:
Predict the output of each line, then explain the difference between parseInt, parseFloat and Number.

console.log(parseInt("10px"));
console.log(Number("10px"));
console.log(parseInt("0x10"));
console.log(parseFloat("1.9e3"));
console.log(parseInt(0.0000005));

